 @Autowired JourneyService journey;@Autowired TaskEvidenceService evidence;@Autowired PollActionService actions;@Autowired MomentService moments;
 @Autowired TaskService tasks;@Autowired PollService polls;@Autowired UserRepository users;@Autowired GroupRepository groups;@Autowired GroupMembershipRepository members;@Autowired ActivityRepository activities;@Autowired ActivityParticipantRepository participants;
