 record F(UUID group,UUID activity,UUID owner,UUID member,UUID outsider){}
 UUID user(){UUID u=UUID.randomUUID();Instant n=Instant.now();users.save(new UserEntity(u,u+"@r10.test","u"+u.toString().substring(0,8),"R10 QA",UserStatus.ACTIVE,n,n));return u;}
 F fixture(){Instant n=Instant.now();UUID o=user(),m=user(),x=user(),g=UUID.randomUUID(),a=UUID.randomUUID();groups.save(new GroupEntity(g,"Journey QA",null,null,GroupStatus.ACTIVE,o,n,n));activities.save(new ActivityEntity(a,g,o,"Đi Ba Vì",null,ActivityStatus.CONFIRMED,null,null,null,null,null,n,n));for(UUID u:List.of(o,m)){members.save(new GroupMembershipEntity(UUID.randomUUID(),g,u,u.equals(o)?GroupRole.OWNER:GroupRole.MEMBER,GroupMembershipStatus.ACTIVE,n,null));participants.save(new ActivityParticipantEntity(UUID.randomUUID(),a,u,ActivityRsvpStatus.GOING,null,n,n,n));}return new F(g,a,o,m,x);}
 Save request(UUID id,String title,Instant expected){return new Save(id,title,"Notes",Instant.now().plusSeconds(86400),null,"Ba Vì",null,null,expected);}
 Stop stop(F f){return journey.create(f.activity(),f.owner(),request(UUID.randomUUID(),"Leo núi",null));}
 String key(F f,UUID actor){String k=refs.newKey(UploadCategory.MOMENT_IMAGE,f.group(),actor);when(storage.head(k)).thenReturn(new ObjectStorageService.ObjectMetadata("image/png",42,Map.of("declared-size","42","original-file-name",Base64.getUrlEncoder().withoutPadding().encodeToString("qa.png".getBytes()))));when(storage.presignGet(eq(k),any())).thenReturn(new ObjectStorageService.PresignedObject("https://private.test/r10",Instant.now().plusSeconds(60),Map.of()));return k;}
 UUID task(F f){return tasks.create(f.activity(),f.owner(),new CreateTaskRequest("Mua rau","",List.of(f.member()),null)).id();}
 @Test void stopCrudValidationPermissionsStaleAndReorder(){F f=fixture();var s=stop(f);assertThrows(BusinessException.class,()->journey.get(f.activity(),s.id(),f.outsider()));assertThrows(BusinessException.class,()->journey.create(f.activity(),f.member(),request(UUID.randomUUID(),"No",null)));var updated=journey.edit(f.activity(),s.id(),f.owner(),request(s.id(),"Đi suối",s.updatedAt()));assertThrows(BusinessException.class,()->journey.edit(f.activity(),s.id(),f.owner(),request(s.id(),"Stale",s.updatedAt())));assertThrows(BusinessException.class,()->journey.edit(f.activity(),s.id(),f.owner(),new Save(s.id(),"Bad","",updated.startsAt(),updated.startsAt().minusSeconds(1),"",null,null,updated.updatedAt())));var b=stop(f);List<UUID> old=List.of(s.id(),b.id()),order=List.of(b.id(),s.id());journey.reorder(f.activity(),f.owner(),new Reorder(old,order));assertEquals(order,journey.reorder(f.activity(),f.owner(),new Reorder(old,order)).stops().stream().map(Stop::id).toList());var latest=journey.get(f.activity(),s.id(),f.owner());journey.delete(f.activity(),s.id(),f.owner(),latest.updatedAt());assertEquals(1,journey.journey(f.activity(),f.member()).stops().size());}
 @Test void concurrentRetryAndStateLifecycleRevocation()throws Exception{F f=fixture();var req=request(UUID.randomUUID(),"Same",null);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(()->journey.create(f.activity(),f.owner(),req));var two=pool.submit(()->journey.create(f.activity(),f.owner(),req));assertEquals(one.get().id(),two.get().id());}var s=journey.journey(f.activity(),f.owner()).stops().getFirst();var done=journey.state(f.activity(),s.id(),f.owner(),new State(Status.COMPLETED,s.updatedAt()));assertThrows(BusinessException.class,()->journey.state(f.activity(),s.id(),f.owner(),new State(Status.PLANNED,done.updatedAt())));db.update("UPDATE group_memberships SET status='LEFT',ended_at=now() WHERE group_id=? AND user_id=?",f.group(),f.member());assertThrows(BusinessException.class,()->journey.journey(f.activity(),f.member()));}
 @Test void plannedTimeDoesNotGateEarlyStartCheckinOrCompletion(){F f=fixture();var s=stop(f);assertTrue(s.startsAt().isAfter(Instant.now().plusSeconds(3600)));assertTrue(s.canCheckIn());assertTrue(s.canChangeStatus());var first=journey.checkIn(f.activity(),s.id(),f.member(),new CheckIn(UUID.randomUUID(),"Early arrival",List.of(key(f,f.member())),Instant.now()));assertNotNull(first.receivedAt());var active=journey.state(f.activity(),s.id(),f.owner(),new State(Status.IN_PROGRESS,s.updatedAt()));assertEquals(Status.IN_PROGRESS,active.status());assertTrue(active.canCheckIn());journey.checkIn(f.activity(),s.id(),f.member(),new CheckIn(UUID.randomUUID(),"Early work",List.of(key(f,f.member())),Instant.now()));var done=journey.state(f.activity(),s.id(),f.owner(),new State(Status.COMPLETED,active.updatedAt()));assertEquals(Status.COMPLETED,done.status());assertFalse(done.canChangeStatus());assertFalse(done.canCheckIn());assertEquals(2,journey.checkIns(f.activity(),s.id(),f.owner(),null).items().size());}
 @Test void checkinCanonicalMomentAlbumPrivacyAndImmutableContext(){F f=fixture();var s=stop(f);var r=new CheckIn(UUID.randomUUID(),"Camera QA",List.of(key(f,f.member())),Instant.now());var check=journey.checkIn(f.activity(),s.id(),f.member(),r);journey.checkIn(f.activity(),s.id(),f.member(),r);assertEquals("CAMERA_CLIENT_DECLARED",check.source());assertNotNull(check.receivedAt());assertEquals(1,journey.checkIns(f.activity(),s.id(),f.owner(),null).items().size());var album=moments.saveAlbum(f.group(),f.owner(),new MomentDtos.SaveAlbum(UUID.randomUUID(),f.activity(),"QA album",""),false);moments.items(album.id(),f.owner(),check.moment().media().stream().map(MomentDtos.Media::id).toList(),true);assertEquals(1,moments.albumMedia(album.id(),f.member(),null).items().size());assertThrows(BusinessException.class,()->moments.edit(check.moment().id(),f.member(),new MomentDtos.EditMoment("Wrong context",null)));assertThrows(BusinessException.class,()->moments.mediaAccess(check.moment().media().getFirst().id(),f.outsider()));}
 @Test void rollbackLeavesNoMomentAndCommitUsesExistingSocket()throws Exception{F f=fixture();var s=stop(f);var req=new CheckIn(UUID.randomUUID(),"rollback",List.of(key(f,f.member())),null);var socket=mock(org.springframework.web.socket.WebSocketSession.class);when(socket.getId()).thenReturn("r10-"+f.owner());when(socket.isOpen()).thenReturn(true);realtime.register(socket,f.owner());realtime.command(socket,"{\"type\":\"SUBSCRIBE_SCOPE\",\"scope\":\"activity:"+f.activity()+"\"}");awaitDelivery();clearInvocations(socket);new TransactionTemplate(tx).executeWithoutResult(t->{journey.checkIn(f.activity(),s.id(),f.member(),req);t.setRollbackOnly();});assertEquals(0,db.queryForObject("SELECT count(*) FROM group_moments WHERE id=?",Integer.class,req.clientRequestId()));verify(socket,never()).sendMessage(any());journey.checkIn(f.activity(),s.id(),f.member(),req);awaitDelivery();verify(socket,atLeastOnce()).sendMessage(argThat(m->m.getPayload().toString().contains("ACTIVITY_STOP_CHECKIN_CREATED")));realtime.unregister(socket);}
 @Test void legacyTaskAndReviewRequirementCannotBeBypassed(){F f=fixture();UUID t=task(f);tasks.changeStatus(t,f.member(),new UpdateTaskStatusRequest(TaskStatus.DONE));tasks.changeStatus(t,f.member(),new UpdateTaskStatusRequest(TaskStatus.TODO));evidence.configure(t,f.owner(),new ActionDtos.Configure(ActionDtos.Mode.REQUIRE_REVIEW,stop(f).id()));assertThrows(BusinessException.class,()->tasks.changeStatus(t,f.member(),new UpdateTaskStatusRequest(TaskStatus.DONE)));var r=new ActionDtos.Submit(UUID.randomUUID(),ActionDtos.Source.CAMERA_CLIENT_DECLARED,"Vegetables",List.of(key(f,f.member())));evidence.submit(t,f.member(),r);assertEquals(TaskStatus.TODO,tasks.get(t,f.owner()).status());assertTrue(tasks.get(t,f.owner()).permissions().canManageAssignees());assertFalse(tasks.get(t,f.owner()).permissions().canDelete());assertFalse(tasks.get(t,f.member()).permissions().canCompleteWithoutEvidence());assertThrows(BusinessException.class,()->evidence.review(t,r.clientRequestId(),f.member(),new ActionDtos.Review(UUID.randomUUID(),true,"")));evidence.review(t,r.clientRequestId(),f.owner(),new ActionDtos.Review(UUID.randomUUID(),true,"Looks good"));assertEquals(TaskStatus.DONE,tasks.get(t,f.member()).status());assertThrows(BusinessException.class,()->tasks.delete(t,f.owner()));}
 @Test void rejectionHistoryAndReassignmentRejectStaleApproval(){F f=fixture();UUID t=task(f);evidence.configure(t,f.owner(),new ActionDtos.Configure(ActionDtos.Mode.REQUIRE_REVIEW,null));UUID first=UUID.randomUUID();evidence.submit(t,f.member(),new ActionDtos.Submit(first,ActionDtos.Source.GALLERY_UPLOAD,"Gallery",List.of(key(f,f.member()))));evidence.review(t,first,f.owner(),new ActionDtos.Review(UUID.randomUUID(),false,"Retake"));UUID next=UUID.randomUUID();evidence.submit(t,f.member(),new ActionDtos.Submit(next,ActionDtos.Source.CAMERA_CLIENT_DECLARED,"Retry",List.of(key(f,f.member()))));tasks.update(t,f.owner(),new UpdateTaskRequest("Changed",null,null,List.of(f.owner())));assertThrows(BusinessException.class,()->evidence.review(t,next,f.owner(),new ActionDtos.Review(UUID.randomUUID(),true,"Stale")));assertEquals(2,evidence.get(t,f.owner(),null).evidence().size());}
 @Test void directEvidenceCompletesOnceAndStaysPrivate(){F f=fixture();UUID t=task(f);evidence.configure(t,f.owner(),new ActionDtos.Configure(ActionDtos.Mode.DIRECT_COMPLETE,null));var r=new ActionDtos.Submit(UUID.randomUUID(),ActionDtos.Source.CAMERA_CLIENT_DECLARED,"Direct",List.of(key(f,f.member())));var result=evidence.submit(t,f.member(),r);assertEquals(TaskStatus.DONE,result.task().status());evidence.submit(t,f.member(),r);assertEquals(1,evidence.get(t,f.owner(),null).evidence().size());UUID media=result.evidence().getFirst().media().getFirst().id();assertNotNull(evidence.media(t,media,f.owner()));assertThrows(BusinessException.class,()->evidence.media(t,media,f.outsider()));assertTrue(moments.feed(f.group(),f.owner(),null,null).items().isEmpty());}
 @Test void multiChoicePollConvertsToBothTargetsIdempotentlyAndRollbackIsAtomic(){F f=fixture();var p=polls.create(f.activity(),f.owner(),new CreatePollRequest("Go where?",PollType.MULTIPLE_CHOICE,List.of("Leo núi","Đi suối"),false,2,VoteVisibility.ANONYMOUS,ResultVisibility.IMMEDIATE,null));polls.vote(p.id(),f.member(),new VotePollRequest(p.options().stream().map(PollOptionResponse::id).toList()));var r=new ActionDtos.Convert(UUID.randomUUID(),p.options().getFirst().id(),f.activity(),ActionDtos.Target.STOP,"",Instant.now().plusSeconds(86400),null,"Ba Vì",null,List.of());new TransactionTemplate(tx).executeWithoutResult(t->{actions.convert(p.id(),f.owner(),r);t.setRollbackOnly();});assertTrue(journey.journey(f.activity(),f.owner()).stops().isEmpty());var link=actions.convert(p.id(),f.owner(),r);assertEquals(link.id(),actions.convert(p.id(),f.owner(),r).id());assertEquals(link.id(),actions.convert(p.id(),f.owner(),new ActionDtos.Convert(UUID.randomUUID(),r.optionId(),r.activityId(),r.target(),r.notes(),r.startsAt(),r.endsAt(),r.locationLabel(),r.dueAt(),r.assigneeUserIds())).id());var task=actions.convert(p.id(),f.owner(),new ActionDtos.Convert(UUID.randomUUID(),p.options().get(1).id(),f.activity(),ActionDtos.Target.TASK,"",null,null,"",null,List.of(f.member())));assertEquals("Go where?",tasks.get(task.taskId(),f.member()).title());assertEquals(2,actions.context(p.id(),f.member()).links().size());assertThrows(BusinessException.class,()->actions.convert(p.id(),f.outsider(),r));}
 @Test void pollStopAllowsEditedTitleAndKeepsSourceWithoutDuplicate(){F f=fixture();var p=polls.create(f.activity(),f.owner(),new CreatePollRequest("Où aller",PollType.SINGLE_CHOICE,List.of("Ba Vì","Hà Nội"),false,null,VoteVisibility.ANONYMOUS,ResultVisibility.IMMEDIATE,null));polls.vote(p.id(),f.member(),new VotePollRequest(List.of(p.options().getFirst().id())));var request=new ActionDtos.Convert(UUID.randomUUID(),p.options().getFirst().id(),f.activity(),ActionDtos.Target.STOP,"QA",Instant.now().plusSeconds(86400),null,"QA",null,List.of(),null,"Chặng QA đã sửa");var target=actions.convert(p.id(),f.owner(),request);var stop=journey.get(f.activity(),target.stopId(),f.member());assertEquals("Chặng QA đã sửa",stop.title());assertTrue(stop.notes().contains("Ba Vì"));assertEquals("Ba Vì",target.sourceOption());assertEquals(target.id(),actions.convert(p.id(),f.owner(),request).id());assertEquals(1,journey.journey(f.activity(),f.owner()).stops().size());}
 @Test void pollTaskUsesQuestionOrExplicitActionTitleAndRetainsChosenOption(){F f=fixture();var p=polls.create(f.activity(),f.owner(),new CreatePollRequest("Mua hoa quả",PollType.SINGLE_CHOICE,List.of("Ở chợ","Ở siêu thị"),false,null,VoteVisibility.PUBLIC,ResultVisibility.IMMEDIATE,null));polls.vote(p.id(),f.member(),new VotePollRequest(List.of(p.options().getFirst().id())));var first=actions.convert(p.id(),f.owner(),new ActionDtos.Convert(UUID.randomUUID(),p.options().getFirst().id(),f.activity(),ActionDtos.Target.TASK,"Mang túi",null,null,"",null,List.of()));var t=tasks.get(first.taskId(),f.owner());assertEquals("Mua hoa quả",t.title());assertTrue(t.description().contains("Phương án đã chọn: Ở chợ"));assertEquals("Ở chợ",first.sourceOption());var custom=actions.convert(p.id(),f.owner(),new ActionDtos.Convert(UUID.randomUUID(),p.options().get(1).id(),f.activity(),ActionDtos.Target.TASK,"",null,null,"",null,List.of(),"Đi mua hoa quả"));assertEquals("Đi mua hoa quả",tasks.get(custom.taskId(),f.owner()).title());assertTrue(tasks.get(custom.taskId(),f.owner()).description().contains("Ở siêu thị"));var retry=actions.convert(p.id(),f.owner(),new ActionDtos.Convert(UUID.randomUUID(),p.options().get(1).id(),f.activity(),ActionDtos.Target.TASK,"",null,null,"",null,List.of(),"Tên khác"));assertEquals(custom.id(),retry.id());assertEquals("Đi mua hoa quả",tasks.get(retry.taskId(),f.owner()).title());}
 @Test void departedAssigneeCannotBeApprovedAndEvidenceAccessIsRevoked(){F f=fixture();UUID t=task(f);evidence.configure(t,f.owner(),new ActionDtos.Configure(ActionDtos.Mode.REQUIRE_REVIEW,null));var r=new ActionDtos.Submit(UUID.randomUUID(),ActionDtos.Source.CAMERA_CLIENT_DECLARED,"Before leave",List.of(key(f,f.member())));evidence.submit(t,f.member(),r);db.update("UPDATE group_memberships SET status='LEFT',ended_at=now() WHERE group_id=? AND user_id=?",f.group(),f.member());assertThrows(BusinessException.class,()->evidence.review(t,r.clientRequestId(),f.owner(),new ActionDtos.Review(UUID.randomUUID(),true,"No")));assertThrows(BusinessException.class,()->evidence.get(t,f.member(),null));assertEquals(TaskStatus.TODO,tasks.get(t,f.owner()).status());}
 @Test void concurrentReviewIsIdempotentAndCanonicalStatusHistoryIsSingle()throws Exception{F f=fixture();UUID t=task(f);evidence.configure(t,f.owner(),new ActionDtos.Configure(ActionDtos.Mode.REQUIRE_REVIEW,null));var r=new ActionDtos.Submit(UUID.randomUUID(),ActionDtos.Source.CAMERA_CLIENT_DECLARED,"Review",List.of(key(f,f.member())));evidence.submit(t,f.member(),r);var review=new ActionDtos.Review(UUID.randomUUID(),true,"Accepted");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(()->evidence.review(t,r.clientRequestId(),f.owner(),review));var two=pool.submit(()->evidence.review(t,r.clientRequestId(),f.owner(),review));assertEquals(TaskStatus.DONE,one.get().task().status());assertEquals(TaskStatus.DONE,two.get().task().status());}assertEquals(1,db.queryForObject("SELECT count(*) FROM task_evidence_reviews WHERE evidence_id=?",Integer.class,r.clientRequestId()));assertEquals(1,db.queryForObject("SELECT count(*) FROM task_status_history WHERE task_id=? AND to_status='DONE'",Integer.class,t));}
 @Test void hiddenResultsCannotConvertAndClosedPollRetainsSourceOnOptionDeletion(){F f=fixture();var p=polls.create(f.activity(),f.owner(),new CreatePollRequest("Private results",PollType.SINGLE_CHOICE,List.of("One","Two"),false,null,VoteVisibility.ANONYMOUS,ResultVisibility.AFTER_CLOSE,null));polls.vote(p.id(),f.member(),new VotePollRequest(List.of(p.options().getFirst().id())));var req=new ActionDtos.Convert(UUID.randomUUID(),p.options().getFirst().id(),f.activity(),ActionDtos.Target.TASK,"",null,null,"",null,List.of());assertThrows(BusinessException.class,()->actions.convert(p.id(),f.owner(),req));polls.close(p.id(),f.owner());var link=actions.convert(p.id(),f.owner(),req);db.update("DELETE FROM poll_votes WHERE poll_id=?",p.id());db.update("DELETE FROM polls WHERE id=?",p.id());var origin=actions.targetSources(ActionDtos.Target.TASK,link.taskId(),f.member()).getFirst();assertNull(origin.pollId());assertEquals("One",origin.sourceOption());tasks.delete(link.taskId(),f.owner());assertNull(db.queryForObject("SELECT task_id FROM poll_conversion_links WHERE id=?",UUID.class,link.id()));}

